svg.wm{aspect-ratio:718.9/131.1;overflow:visible;flex:0 0 auto}.h-ttl svg.wm{width:132px}.ln-brand svg.wm{width:148px}.ln-foot .ln-brand svg.wm{width:121px}#gate .g-brand svg.wm{width:197px}#splash .sp-name svg.wm{width:263px}svg.t3m{display:block;flex:0 0 auto;overflow:hidden}
